329  void MleRouter::SetStateLeader(uint16_t aRloc16)
   330  {
   331      SetRloc16(aRloc16);
   332
   333      SetRole(OT_DEVICE_ROLE_LEADER);
   334      SetAttachState(kAttachStateIdle);
   335      mAttachCounter = 0;
   336      mAttachTimer.Stop();
   337      mMessageTransmissionTimer.Stop();
   338      mAdvertiseTimer.Stop();
   339      ResetAdvertiseInterval();
   340      AddLeaderAloc();
   341
   342      Get<ThreadNetif>().SubscribeAllRoutersMulticast();
   343      mPreviousPartitionIdRouter = mLeaderData.GetPartitionId();
   344      mStateUpdateTimer.Start(kStateUpdatePeriod);
   345
   346      Get<NetworkData::Leader>().Start();
   347      Get<MeshCoP::ActiveDataset>().StartLeader();
   348      Get<MeshCoP::PendingDataset>().StartLeader();
   349      Get<Coap::Coap>().AddResource(mAddressSolicit);
   350      Get<Coap::Coap>().AddResource(mAddressRelease);
   351      Get<Ip6::Ip6>().SetForwardingEnabled(true);
   352      Get<Ip6::Mpl>().SetTimerExpirations(kMplRouterDataMessageTimerExpirations);
   353      Get<Mac::Mac>().SetBeaconEnabled(true);
   354      Get<AddressResolver>().Clear();
   355
   356      // remove children that do not have matching RLOC16
   357      for (ChildTable::Iterator iter(GetInstance(), ChildTable::kInStateValidOrRestoring); !iter.IsDone(); iter++)
   358      {
   359          if (GetRouterId(iter.GetChild()->GetRloc16()) != mRouterId)
   360          {
   361              RemoveNeighbor(*iter.GetChild());
   362          }
   363      }
   364
   365      otLogNoteMle("Leader partition id 0x%x", mLeaderData.GetPartitionId());
   366  }
